#!/usr/bin/env python3
"""Inline local assets; embeds SVGs too, so the export has no local-file links."""
import argparse,pathlib,re,json,base64,hashlib,mimetypes
ROOT=pathlib.Path(__file__).resolve().parent
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output',type=pathlib.Path,default=ROOT.parent/'ScienceGym-Task-Explorer.html')
args=parser.parse_args()
page=(ROOT/'index.html').read_text()
route_count=sum(f['routes'] for f in json.loads((ROOT/'manifest.json').read_text())['families'])
page=page.replace('<link rel="stylesheet" href="styles.css">','<style>'+(ROOT/'styles.css').read_text()+'</style>')
for name in ['README.md','docs/ADAPTERS.md']:page=page.replace('href="'+name+'"','href="#standaloneGuide"')
page=page.replace('<footer>', '<details id="standaloneGuide"><summary>Offline guide and verification boundary</summary><div><p>Choose a family and branch, then click an operation. Search highlights matches without hiding route steps. Use Dependencies &amp; choices for declared partial orders and Acceptance &amp; unknowns for evaluator contracts.</p><p>Source scientific stages and authored robot handling remain distinct. Arrows indicate reference list order. Loops are unexpanded contracts; repeated IDs retain their occurrence index. Acquisition, data, cooling, EmVP and prismatic membership obligations do not imply unspecified chronology. Prismatic material/target and thickness/target nesting remains symbolic; null counts block expansion. EmVP cage conditions retain separate source routes, and comparison coverage never converts states or sites into independent specimens.</p><p>SVG overview downloads the embedded diagram for the selected family. Earlier-family source links open pinned public snapshots. The five recent families embed their exact local source JSON and original asset guide/render bytes; opening an embedded file does not assert remote publication. Cooling retains six symbolic loop contracts, conditional receipt gates, unknown counts and required physical transfer instances. Mechanical views preserve typed forward/adjoint bindings, physical transfers, ring concurrency and conditional preparation. Numerical training is not physical self-updating, and ring torque is semi-experimental rather than directly measured. Proposals and source-missing gates retain their source-specific status. Assembly views preserve scoped granular/thermal dependency gates, symbolic repeats, actual sample/packing lineage and separate device ownership. Beaded exclusive preparation choices and typed loop bindings remain unselected templates. Source-section navigation counts do not create new experiments. Final materials views preserve Horn matched-map and numerical distinctions, ReMM source_complete=false with unread panels/movies, and cold-shape closed qualified hazardous services. Derived fits never become independent validation. Condition schedules, loops and sample counts remain symbolic. Gear recipes retain authored order, separate preparation/condition templates, specimen identities and unresolved geometry conflicts. Numerical operations and illustrative demonstrations never gain physical credit. Hydrogel memberships retain per-service phase order without cross-service chronology; four Extended Data image sets remain uninspected, power/data conflicts remain open, Video 9 is accelerated 20 times, and all hazardous processes remain closed qualified services. Cross-disciplinary views preserve atmospheric mount leases and observed/simulated data separation; AFM bounded imaging, retained probes, target exchange and final teardown; Martian closed facility services and sample/region lineage; and transistor unordered inventories, lifecycle, typed cohorts, safe zero and unresolved conflicts. Incomplete fabrication and prospective records never earn physical completion. The explorer distinguishes 35 paper-level designs and three bounded subsets. Paired views preserve qualification/flow/direction hold defaults and exact profile/lineage/exclusion contracts, and link existing original 3D guides/static renders without interactive web physics. Woven retains 24 scientific routes plus a separate qualification-hold view, 48 symbolic operations, 11 static groups and 43 symbolic anchors. The source suite reports 96 synthetic configurations; the viewer preserves their count and JSON contracts. Lockable origami adds 30 source branches plus four hold views; varactor adds 28 source branches plus a default hold. Source memberships, conditional recovery, fabrication/intake ancestry, open-path origami work, varactor shared-specimen revisions and source access gaps stay explicit. Wetting adds sixteen design routes plus a metadata-only qualification hold; cadmium fiducial preparation and high-voltage deposition stay external closed boundaries. Six movie samples are not full playback and workbook numerical cells remain unread. Arc-Morph adds seven physical route families, two auxiliary records, six nonmanual dispositions and a metadata-only qualification hold. Its thirty-one operation templates retain repeated transport occurrences and separate phase bodies; one symbolic same-specimen loop keeps eight configuration slots without inventing repeats. Fixture-specific closeout alternatives stay conditional, ten source conflicts and fourteen unknowns stay open, and original static geometry remains illustrative. Mid-infrared adds eight experimental branches, twenty-two authored operation templates, five separate reference views and a metadata-only qualification hold. All controls, lineage, failed attempts and supported holds remain exact. Approximately 10 Hz is confined to analog 16x16, fourteen qualification gaps stay open, and raw data and modified source code remain unavailable. These are whole-paper design records, not reproduction. Source conflicts, closed service qualification, independent receipts, physical/model separation and prepared-intake lineage remain exact. This file has no external runtime dependencies.</p><p>Verified: source-equality and structural tests, all CURRENT_ROUTE_COUNT route views in a mocked DOM, portable SVG rendering. Not verified: actual browser rendering, touch/responsive layout or scientific/robot execution. Browser file and localhost access were blocked by the environment policy.</p></div></details><footer>')
page=page.replace('CURRENT_ROUTE_COUNT',str(route_count))
svgs={f.stem:f.read_text() for f in (ROOT/'diagrams').glob('*.svg')}
def script_escape(s):return re.sub(r'</script',r'<\\/script',s,flags=re.I)
embedded={}
for entry in json.loads((ROOT/'manifest.json').read_text())['families']:
    f=json.loads((ROOT/'data'/(entry['id']+'.json')).read_text())
    if f.get('source_link_mode')!='repository_relative_frozen_local_snapshot': continue
    for item in list(f['source_files'].values())+f['asset_links']:
        url=item['url']; local=(ROOT/url).resolve()
        local.relative_to(ROOT.parent.parent.resolve())
        payload=local.read_bytes()
        if hashlib.sha256(payload).hexdigest()!=item['sha256']: raise ValueError('Embedded source/asset hash mismatch: '+url)
        embedded[url]={'mime':mimetypes.guess_type(local.name)[0] or 'application/octet-stream',
                       'base64':base64.b64encode(payload).decode('ascii')}
page=page.replace('<script src="app.js"></script>','<script>window.SCIENCEGYM_EMBEDDED_FILES='+script_escape(json.dumps(embedded,separators=(',',':')))+';</script><script src="app.js"></script>')
page=page.replace('<script src="app.js"></script>','<script>window.SCIENCEGYM_SVGS='+script_escape(json.dumps(svgs,ensure_ascii=False))+';</script><script src="app.js"></script>')
page=re.sub(r'<script src="([^"]+)"></script>',lambda m:'<script>'+script_escape((ROOT/m.group(1)).read_text())+'</script>',page)
out=args.output;out.write_text(page)
assert not re.search(r'(?:src|href)="(?!https?:|#)(?!\s*$)[^"]+"',page), 'Unresolved local link'
print(out, out.stat().st_size)
